import express from "express";
import path from "path";
import fs from "fs";
import { spawn } from "child_process";
import { createServer as createViteServer } from "vite";

const app = express();
const PORT = 3000;

app.use(express.json());

// Global status state
let generationState = {
  status: "idle", // 'idle' | 'generating' | 'completed' | 'error'
  totalPages: 1000,
  minChars: 5000,
  generatedCount: 0,
  elapsedSec: 0,
  totalMB: 0,
  logs: [] as string[],
  error: null as string | null
};

// Ensure dist directory exists
const distDir = path.join(process.cwd(), "dist");
if (!fs.existsSync(distDir)) {
  fs.mkdirSync(distDir, { recursive: true });
}

// ----------------------------------------------------------------------------
// API ENDPOINTS
// ----------------------------------------------------------------------------

// 1. Get status & stats
app.get("/api/status", (req, res) => {
  try {
    const files = fs.readdirSync(distDir).filter(f => f.endsWith(".html"));
    let totalBytes = 0;
    files.forEach(file => {
      try {
        const stat = fs.statSync(path.join(distDir, file));
        totalBytes += stat.size;
      } catch (e) {
        // ignore
      }
    });

    res.json({
      ...generationState,
      existingFilesCount: files.length,
      totalMB: (totalBytes / (1024 * 1024)).toFixed(2),
      sampleFiles: files.slice(0, 50)
    });
  } catch (err) {
    res.status(500).json({ error: String(err) });
  }
});

// 2. Trigger build.js execution
app.post("/api/generate", (req, res) => {
  if (generationState.status === "generating") {
    return res.status(400).json({ error: "Generation already in progress" });
  }

  const pages = parseInt(req.body.totalPages || "1000", 10);
  const minChars = parseInt(req.body.minChars || "5000", 10);

  generationState = {
    status: "generating",
    totalPages: pages,
    minChars: minChars,
    generatedCount: 0,
    elapsedSec: 0,
    totalMB: 0,
    logs: [`[${new Date().toLocaleTimeString()}] Triggering node build.js ${pages} ${minChars}...`],
    error: null
  };

  const child = spawn("node", ["build.js", String(pages), String(minChars)], {
    cwd: process.cwd(),
    env: process.env
  });

  child.stdout.on("data", (data) => {
    const text = data.toString().trim();
    if (text) {
      generationState.logs.push(text);
      if (generationState.logs.length > 200) {
        generationState.logs.shift();
      }

      // Parse progress if matched
      const progressMatch = text.match(/Generated ([\d,]+) \/ ([\d,]+)/);
      if (progressMatch) {
        generationState.generatedCount = parseInt(progressMatch[1].replace(/,/g, ''), 10);
      }
    }
  });

  child.stderr.on("data", (data) => {
    const text = data.toString().trim();
    if (text) {
      generationState.logs.push(`[ERR] ${text}`);
    }
  });

  child.on("close", (code) => {
    if (code === 0) {
      generationState.status = "completed";
      generationState.logs.push(`[${new Date().toLocaleTimeString()}] ✅ Build completed successfully!`);
    } else {
      generationState.status = "error";
      generationState.error = `build.js exited with process code ${code}`;
      generationState.logs.push(`[${new Date().toLocaleTimeString()}] ❌ Build failed with exit code ${code}`);
    }
  });

  res.json({ message: "Generation started", state: generationState });
});

// 3. Serve generated static files for preview iframe
app.get(["/api/preview", "/api/preview/*"], (req, res) => {
  let paramPath = (req.params as Record<string, string>)[0] || "index.html";
  if (!paramPath || paramPath === "/") paramPath = "index.html";

  let filePath = path.join(distDir, paramPath);

  if (!fs.existsSync(filePath)) {
    if (fs.existsSync(filePath + ".html")) {
      filePath = filePath + ".html";
    } else if (fs.existsSync(path.join(filePath, "index.html"))) {
      filePath = path.join(filePath, "index.html");
    }
  }

  if (!fs.existsSync(filePath)) {
    return res.status(404).send(`
      <!DOCTYPE html>
      <html>
        <body style="background: #0f172a; color: #f8fafc; font-family: sans-serif; display: flex; align-items: center; justify-content: center; height: 100vh; margin: 0;">
          <div style="text-align: center; padding: 2rem; background: #1e293b; border-radius: 12px; border: 1px solid #334155;">
            <h2 style="color: #f59e0b;">File Not Found</h2>
            <p>The requested route/file <code>${paramPath}</code> does not exist in <code>dist/</code>.</p>
            <p style="color: #94a3b8;">Click <strong>Execute node build.js</strong> in the control panel to generate HTML pages!</p>
          </div>
        </body>
      </html>
    `);
  }

  res.sendFile(filePath);
});

// 4. View build.js source code
app.get("/api/code/buildjs", (req, res) => {
  try {
    const buildJsPath = path.join(process.cwd(), "build.js");
    const code = fs.readFileSync(buildJsPath, "utf8");
    res.json({ code });
  } catch (err) {
    res.status(500).json({ error: String(err) });
  }
});

// Serve dist directory statically under /dist-static
app.use("/dist-static", express.static(distDir));

// Vite Middleware for Development / Production Fallback
async function startServer() {
  if (process.env.NODE_ENV !== "production") {
    const vite = await createViteServer({
      server: { middlewareMode: true },
      appType: "spa",
    });
    app.use(vite.middlewares);
  } else {
    app.use(express.static(distDir));
    app.get("*", (req, res) => {
      res.sendFile(path.join(distDir, "index.html"));
    });
  }

  app.listen(PORT, "0.0.0.0", () => {
    console.log(`Server running on http://0.0.0.0:${PORT}`);
  });
}

startServer();
